mapper.select:
SELECT id, biz_id, account_id, user_id, amount, status, created_at, updated_at
FROM forma_credit_hold
WHERE biz_id = #{id}

mapper.update:
UPDATE forma_credit_hold
SET status = #{newStatus},
    updated_at = #{updatedAt}
WHERE biz_id = #{id}
  AND user_id = #{userId}
  AND status = 'ACTIVE'

mapper.select:
SELECT id, biz_id, account_id, user_id, amount, status, created_at, updated_at
FROM forma_credit_hold
WHERE user_id = #{userId}
  AND status = 'SETTLED'
ORDER BY updated_at DESC
LIMIT #{limit}
